function dominoEndpointLabel(st,side){
 const pip=n=>Number.isInteger(n)&&n>=0?String(n):'unknown';
 if(!st.trains)return 'Play selected domino at '+side+' open end, matching '+pip(st.ends?.[side]);
 const id=side.slice(6),train=st.trains[id];
 const title=id==='mexican'?'Mexican train':nameOf(Number(id))+' train';
 const pending=st.pendingDouble!==null&&st.pendingDouble!==undefined&&st.pendingDouble!==''?String(st.pendingDouble):null;
 return 'Play selected domino at '+title+', matching '+pip(train?.end)+', '+(train?.open?'open to all players':'closed to other players')+(pending===id?', outstanding double must be covered':pending?', another train has an outstanding double to cover first':'');
}
